content.text:
        cands.append((alt[0], alt[1]))
    best = None
    best_score = None
    for cy, cq in cands:
        col = model.columns(cy, cq) - model.c
        colv = float(np.max(col)) if col.size else 0.0
        gap = abs(model.lower_bound(cy, cq) - target)
        mag = max(float(np.max(np.abs(cy))) if cy.size else 0.0,
                  float(np.max(np.abs(cq))) if cq.size else 0.0)
        score = (colv, gap, mag)
        if best_score is None or score < best_score:
            best_score = score
            best = (cy, cq)
    if best is None:
        best = (np.zeros(model.r), np.zeros(model.k))
    return best


def _optimal_payload(model, prob, flows, loads, mlu, migration, y, q):
    return {
        "epoch": prob["epoch"],
        "status": "optimal",
        "flows": _nest(flows, prob["shapes"]),
        "loads": [_clean(v) for v in loads.tolist()],
        "mlu": mlu,
        "migration": migration,
        "dual": {
            "inequality": [_clean(v) for v in np.asarray(y).tolist()],
            "equality": [_clean(v) for v in np.asarray(q).tolist()],
        },
    }


def _infeasible_payload(prob, y, q):
    return {
        "epoch": prob["epoch"],
        "status": "infeasible",
        "certificate": {
            "inequality": [_clean(v) for v in np.asarray(y).tolist()],
            "equality": [_clean(v) for v in np.asarray(q).tolist()],
        },
    }


def _marginals(model, res):
    try:
        y = np.asarray(res.ineqlin.marginals, dtype=np.float64).copy()
    except Exception:
        y = None
    if model.E is not None:
        try:
            q = np.asarray(res.eqlin.marginals, dtype=np.float64).copy()
        except Exception:
            q = None
    else:
        q = np.zeros(0, dtype=np.float64)
    if y is None or y.size != model.r:
        return None, None
    if q is None or q.size != model.k:
        return None, None
    return y, q


# The verifier accepts a primal whose canonical violations are within 1e-5 and
# a dual whose column slack is within 1e-7, with |mlu - L| <= 2e-5.  These
# internal gates are deliberately stricter.
PRIMAL_GATE = 5.0e-6
DUAL_COL_GATE = 1.0e-9
DUAL_GAP_GATE = 1.0e-5


def _candidate(model, prob, res):
    """Build a (violation, payload) pair from a primal LP result, or None."""
    if res is None or res.x is None:
        return None
    x = np.asarray(res.x, dtype=np.float64)
    if x.size != model.n or not np.all(np.isfinite(x)):
        return None
    flows, loads, mlu, migration = _allocation(model, x)
    if not (np.isfinite(mlu) and np.isfinite(migration)):
        return None
    viol = _primal_violation(model, flows, mlu)
    if not np.isfinite(viol):
        return None
    y, q = _marginals(model, res)
    if y is None or not _dual_ok(model, y, q, mlu, tol_col=DUAL_COL_GATE,
                                 tol_gap=DUAL_GAP_GATE):
        y, q = _certificate(model, y, q, mlu)
    payload = _optimal_payload(model, prob, flows, loads, mlu, migration, y, q)
    return viol, payload


def _payload_clean(payload, model):
    """Score a payload: (dual column slack, |mlu - L|, primal violation)."""
    y = np.array(payload["dual"]["inequality"], dtype=np.float64)
    q = np.array(payload["dual"]["equality"], dtype=np.float64)
    flows = [v for row in payload["flows"] for v in row]
    col = model.columns(y, q) - model.c
    colv = float(np.max(col)) if col.size else 0.0
    colv = max(colv, float(np.max(y)) if y.size else 0.0)
    gap = abs(model.lower_bound(y, q) - payload["mlu"])
    viol = _primal_violation(model, flows, payload["mlu"])
    return (colv, gap, viol)


def solve(prob):
    model = Model(prob)
    attempts = (
        {"tight": False, "presolve": True, "limit": 30.0,
         "methods": ("highs",)},
        {"tight": True, "presolve": True, "limit": 12.0,
         "methods": ("highs", "highs-ds")},
        {"tight": True, "presolve": False, "limit": 12.0,
         "methods": ("highs-ipm", "highs-ds")},
    )
    best = None                 # (score tuple, payload)
    saw_infeasible = False
    for cfg in attempts:
        res = _solve_primal(model, tight=cfg["tight"], presolve=cfg["presolve"],
                            limit=cfg["limit"], methods=cfg["methods"])
        if res is None:
            continue
        if res.status == 2:
            saw_infeasible = True
            cert = _farkas(model)
            if cert is not None:
                return _infeasible_payload(prob, cert[0], cert[1])
            continue
        cand = _candidate(model, prob, res)
        if cand is None:
            continue
        viol, payload = cand
        score = _payload_clean(payload, model)
        if best is None or score < best[0]:
            best = (score, payload)
        if score[0] <= DUAL_COL_GATE and score[1] <= 1e-6 and viol <= 1e-9:
            return payload
    if best is not None:
        colv, gap, viol = best[0]
        if colv > DUAL_COL_GATE or gap > DUAL_GAP_GATE or viol > PRIMAL_GATE:
            sys.stderr.write(
                "planner: weak certificate colv=%.3g gap=%.3g viol=%.3g\n"
                % (colv, gap, viol))
        return best[1]
    if saw_infeasible:
        raise Invalid("infeasible without witness")
    raise Invalid("solver failure")


def _nest(flows, shapes):
    out = []
    idx = 0
    for count in shapes:
        out.append([flows[idx + i] for i in range(count)])
        idx += count
    return out


